SELECT c.CategoryId, N'Chicken Meat', N'Fresh and tender chicken meat, suitable for various culinary preparations.', 9.99, N'https://cdn.dummyjson.com/product-images/groceries/chicken-meat/thumbnail.webp', 97, 1, GETDATE()
FROM @CatMap c WHERE c.Slug = N'groceries';
SET @Pid19 = SCOPE_IDENTITY();
IF @Pid19 IS NOT NULL
    INSERT INTO dbo.ProductImage (ProductId, Url, DisplayOrder)
    VALUES (@Pid19, N'https://cdn.dummyjson.com/product-images/groceries/chicken-meat/thumbnail.webp', 0);
IF @Pid19 IS NOT NULL
    INSERT INTO dbo.ProductImage (ProductId, Url, DisplayOrder)
    VALUES (@Pid19, N'https://cdn.dummyjson.com/product-images/groceries/chicken-meat/1.webp', 1);
IF @Pid19 IS NOT NULL
    INSERT INTO dbo.ProductImage (ProductId, Url, DisplayOrder)
    VALUES (@Pid19, N'https://cdn.dummyjson.com/product-images/groceries/chicken-meat/2.webp', 2);

